      const g = s("g", { style: n.path ? "cursor:pointer" : "" }, s("rect", { class: "box", x: p.x, y: p.y, width: W, height: H, rx: ctrl ? 4 : 10 }), s("text", { x: p.x + 10, y: p.y + 16 }, n.name), s("text", { class: "elabel", x: p.x + 10, y: p.y + 30 }, ctrl ? n.kind : n.type || n.kind));
