    catch (e) { body = h("div", { class: "pane" }, h("div", { class: "callout flagConflict" }, h("b", {}, "This view failed to draw"), String((e         )?.message ?? e)), h("pre", {}, String((e         )?.stack ?? ""))); console.error(e); }
